test_suite:
test('delivers values to subscriber', () => {
  const log = [];
  new Observable(obs => { obs.next(1); obs.next(2); obs.complete(); })
    .subscribe({ next: v => log.push(v), complete: () => {} });
  expect(log).toEqual([1, 2]);
});

test('map transforms values', () => {
  const log = [];
  new Observable(obs => { [1,2,3].forEach(n => obs.next(n)); })
    .map(n => n * 2)
    .subscribe({ next: v => log.push(v) });
  expect(log).toEqual([2, 4, 6]);
});

test('filter only passes matching values', () => {
  const log = [];
  new Observable(obs => { [1,2,3,4,5].forEach(n => obs.next(n)); })
    .filter(n => n % 2 === 0)
    .subscribe({ next: v => log.push(v) });
  expect(log).toEqual([2, 4]);
});

test('unsubscribe stops delivery', () => {
  const log = [];
  let outerObs;
  const sub = new Observable(obs => { outerObs = obs; })
    .subscribe({ next: v => log.push(v) });
  outerObs.next(1);
  sub.unsubscribe();
  outerObs.next(2);
  expect(log).toEqual([1]);
});

