  const log = [];
  new Observable(obs => { [1,2,3,4,5,6].forEach(n => obs.next(n)); })
    .filter(n => n % 2 === 0)
    .map(n => n * n)
    .subscribe({ next: v => log.push(v) });
  expect(log).toEqual([4, 16, 36]);
});

solution:
export class Observable {
  constructor(subscribeFn) {
    this._subscribeFn = subscribeFn;
  }

  subscribe(observer) {
    let active = true;
    const safeObserver = {
      next: (v) => { if (active) observer.next && observer.next(v); },
      error: (e) => { if (active) { active = false; observer.error && observer.error(e); } },
      complete: () => { if (active) { active = false; observer.complete && observer.complete(); } }
    };
    this._subscribeFn(safeObserver);
    return { unsubscribe: () => { active = false; } };
  }

  map(fn) {
    return new Observable(observer => {
      this.subscribe({
        next: v => observer.next(fn(v)),
        error: e => observer.error && observer.error(e),
        complete: () => observer.complete && observer.complete()
      });
    });
  }

  filter(fn) {
    return new Observable(observer => {
      this.subscribe({
        next: v => { if (fn(v)) observer.next(v); },
        error: e => observer.error && observer.error(e),
        complete: () => observer.complete && observer.complete()
      });
    });
  }
}
